from langflow.custom.custom_component.component import Component
from langflow.io import MessageTextInput, MessageInput, Output
from langflow.schema.data import Data


class CustomComponent(Component):
    display_name = "Delete File"
    description = "Deletes a file at the specified path."
    documentation: str = "https://docs.langflow.org/components-custom-components  "
    icon = "trash-2"
    name = "DeleteFileComponent"

    inputs = [
        MessageTextInput(
            name="file_path",
            display_name="File Path",
            info="The path to the file you want to delete.",
            value="",
            required=True,
        ),
        MessageInput(
            name="trigger_input",
            display_name="Trigger Input",
            info="Optional input to act as a trigger. Its value is ignored.",
            advanced=True,
            required=False,
        ),
    ]

    outputs = [
        Output(display_name="Output", name="output", method="delete_file"),
    ]

    def delete_file(self) -> Data:
        path_str = self.file_path.strip()

        if not path_str:
            error_msg = "File path is required."
            self.status = error_msg
            return Data(data={"error": error_msg}, text=error_msg)

        file_path = Path(path_str)

        try:
            if not file_path.is_file():
                if file_path.exists():
                    error_msg = f"Path '{file_path}' exists but is not a file."
                    self.status = error_msg
                    return Data(data={"error": error_msg}, text=error_msg)
                else:
                    error_msg = f"File '{file_path}' does not exist."
                    self.status = error_msg
                    return Data(data={"error": error_msg}, text=error_msg)

            file_path.unlink()

            success_msg = f"File '{file_path}' deleted successfully."
            self.status = success_msg
            return Data(data={"message": success_msg}, text=success_msg)

        except PermissionError:
            error_msg = f"Permission denied: Cannot delete '{file_path}'. Check file permissions."
            self.status = error_msg
            return Data(data={"error": error_msg}, text=error_msg)
        except OSError as e:
            error_msg = f"OS Error while deleting '{file_path}': {str(e)}"
            self.status = error_msg
            return Data(data={"error": error_msg}, text=error_msg)
        except Exception as e:
            error_msg = f"Unexpected error while deleting '{file_path}': {str(e)}"
            self.status = error_msg
            return Data(data={"error": error_msg}, text=error_msg)

