import re

CTRL_RE = re.compile(r"[\x00]")  # Можно расширить: r"[\x00-\x08\x0B\x0C\x0E-\x1F]"


class CustomComponent(Component):
    display_name = "Clean Text Column"
    description = "Removes NUL characters (and optionally other control characters) from the 'text' column of a DataFrame."
    documentation: str = "https://docs.langflow.org/components-custom-components  "
    icon = "filter"
    name = "CleanTextColumnComponent"

    inputs = [
        DataFrameInput(
            name="input_dataframe",
            display_name="Input DataFrame",
            info="DataFrame containing a 'text' column to clean.",
            required=True,
        ),
    ]

    outputs = [
        Output(display_name="Cleaned DataFrame", name="output_dataframe", method="clean_dataframe"),
    ]

    def clean_dataframe(self) -> DataFrame:
        df = self.input_dataframe

        if df is None:
            error_msg = "Error: Input DataFrame is None."
            self.status = error_msg
            return Data(data={"error": error_msg}, text=error_msg)

        def remove_ctrl_chars(text):
            if pd.isna(text):
                return text
            if not isinstance(text, str):
                text = str(text)
            return CTRL_RE.sub("", text)

        df_copy = df.copy()
        df_copy["text"] = df_copy["text"].apply(remove_ctrl_chars)

        # Возвращаем DataFrame обернутый в словарь
        return DataFrame(data=df_copy)

